<script setup lang="ts">
import { onMounted, onUnmounted, ref, watch } from 'vue'
import { fileUrl, request, requestPage } from '../api'
import PaginationControl from '../components/PaginationControl.vue'
const format=ref<'csv'|'pdf'>('csv');const busy=ref(false);const error=ref('');const report=ref<any>(null);const rows=ref<any[]>([]);const page=ref(1);const pageSize=ref(10);const total=ref(0);const pages=ref(0);let pollTimer: number | undefined
function stopPolling(){if(pollTimer) window.clearTimeout(pollTimer);pollTimer=undefined}
async function poll(){if(!report.value?.id)return;try{report.value=await request('/reports/'+report.value.id);if(['queued','running'].includes(report.value.status)){pollTimer=window.setTimeout(poll,1000)}else if(report.value.status==='failed'){error.value='报告生成失败，请重新生成。'}}catch(e){error.value=e instanceof Error?e.message:'报告状态查询失败'}}
async function loadHistory(){try{const result=await requestPage<any>('/reports',{page:page.value,page_size:pageSize.value});rows.value=result.items;total.value=result.meta.total;pages.value=result.meta.pages}catch(e){error.value=e instanceof Error?e.message:'报告历史加载失败'}}
async function create(){stopPolling();busy.value=true;error.value='';report.value=null;try{report.value=await request('/reports/faults',{method:'POST',body:JSON.stringify({format:format.value})});await poll();await loadHistory()}catch(e){error.value=e instanceof Error?e.message:'报告生成失败'}finally{busy.value=false}}
function download(){if(!report.value || report.value.status!=='ready')return;const a=document.createElement('a');a.href=fileUrl('/reports/'+report.value.id+'/download');a.download=report.value.file_name;a.click()}
watch(page, loadHistory);watch(pageSize, () => { page.value = 1; loadHistory() });onMounted(loadHistory);onUnmounted(stopPolling)
</script>
<template><section class="page-view"><div class="page-heading"><div><span class="eyebrow">REPORT CENTER</span><h2>报告中心</h2><p>将当前授权范围内的故障数据导出为可归档文件。</p></div></div><p v-if="error" class="inline-error" role="alert">{{ error }}</p><div class="report-grid"><section class="panel"><span class="eyebrow">FAULT REPORT</span><h3>生成故障报表</h3><p class="muted-text">报告包含设备、严重级别、状态、时间和处理负责人。</p><label class="radio-row"><input v-model="format" type="radio" value="csv" :disabled="busy"> CSV（适合数据处理）</label><label class="radio-row"><input v-model="format" type="radio" value="pdf" :disabled="busy"> PDF（适合归档阅读）</label><button class="button primary" :disabled="busy" :aria-busy="busy" @click="create">{{ busy?'提交中…':'生成报告' }}</button></section><section class="panel" :class="{ 'panel-muted': !report }"><span class="eyebrow">LATEST EXPORT</span><h3>{{ report ? (report.file_name || '报告生成中') : '尚未生成报告' }}</h3><p v-if="report?.status==='queued'">任务已排队，等待 Worker 处理。</p><p v-else-if="report?.status==='running'">正在生成文件，请保持页面打开。</p><p v-else-if="report?.status==='ready'">报告已保存，可以下载。</p><p v-else>生成后这里会出现下载入口。</p><button v-if="report?.status==='ready'" class="button secondary" @click="download">下载文件 ↓</button><button v-if="report?.status==='failed'" class="button secondary" @click="create">重试生成</button></section></div><section class="panel report-history"><div class="panel-heading"><div><span class="eyebrow">EXPORT HISTORY</span><h3>生成记录</h3></div><button class="button secondary compact" type="button" @click="loadHistory">刷新</button></div><div class="table-wrap"><table><thead><tr><th>类型</th><th>格式</th><th>状态</th><th>创建时间</th><th>操作</th></tr></thead><tbody><tr v-for="item in rows" :key="item.id"><td>{{ item.report_type === 'session' ? '会话报告' : '故障报表' }}</td><td>{{ item.format.toUpperCase() }}</td><td><span class="status-text">{{ item.status }}</span></td><td>{{ new Date(item.created_at).toLocaleString('zh-CN') }}</td><td><a v-if="item.status==='ready'" class="text-link" :href="fileUrl('/reports/'+item.id+'/download')">下载</a><span v-else class="muted-text">处理中</span></td></tr><tr v-if="!rows.length"><td colspan="5" class="table-empty">暂无报告记录。</td></tr></tbody></table></div><PaginationControl v-if="total" v-model:page="page" v-model:page-size="pageSize" :pages="pages" :total="total" :start="(page-1)*pageSize+1" :end="Math.min(page*pageSize,total)" /></section></section></template>
